command:
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command "
`$ps=@('CampusNetwork_02','CampusNetwork_03','CampusNetwork_04','CampusNetwork_05','CampusNetwork_06','CampusNetwork_07','CampusNetwork_08','CampusNetwork_09')
`$ns=@('AGG_SW_01','Core_SW_01','PE1','PE2','PE3')
foreach(`$p in `$ps) {
 Write-Output ('===== {0} =====' -f `$p)
 foreach(`$n in `$ns) {
  `$e=[uri]::EscapeDataString('display current-configuration')
  `$u='http://127.0.0.1:3080/v3/projects/{0}/nodes/{1}/command?cmd={2}' -f `$p,`$n,`$e
  try {`$o=(Invoke-RestMethod -Uri `$u).output} catch {continue}
  if(`$o -like 'Error:*not found*') {continue}
  `$m=@(`$o -split '\r?\n' | Where-Object {`$_ -match '(?i)(bpdu-filter|ospf cost|isis cost|traffic-policy|qos car|cir |pir |route-static|ip route |mpls te|srv6|segment-routing)'})
  if(`$m.Count -gt 0) {Write-Output ('--- {0}' -f `$n); `$m | ForEach-Object {Write-Output `$_}}
 }
}"
